import numpy as np
from collections import deque

def parse(txt):
    rows=[]
    for line in txt.splitlines():
        line=line.strip()
        if line and (line[0].isdigit() or line[0] in '0123456789') and ' ' in line and 'Demo' not in line and 'Wrong' not in line and 'Test' not in line and 'Reply' not in line:
            parts=line.split()
            if all(p.isdigit() and len(p)<=2 for p in parts):
                rows.append([int(x) for x in parts])
    return rows

def components(g, color):
    R,C=len(g),len(g[0])
    seen=set(); comps=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]==color and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and g[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                comps.append(sorted(comp))
    return comps

def mind(a,b):
    return min(abs(y1-y2)+abs(x1-x2) for y1,x1 in a for y2,x2 in b)

