from collections import deque as _dq

def feat3(ob, dd):
    f = feat2(ob, dd)
    Gin = dd['Gin']; H, W = len(Gin), len(Gin[0])
    lf = dd['lf']; cy, cx = lf['corner']; Ls = set(lf['L']); cells = set(ob['cells'])
    # flood from corner through bg, find first non-L non-bg cell (BFS order)
    seen = {(cy,cx)}; q = _dq([(cy,cx,0)]); hit = None; hitd = None
    while q:
        y,x,d = q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            y2,x2 = y+dy,x+dx
            if 0<=y2<H and 0<=x2<W and (y2,x2) not in seen and (y2,x2) not in Ls:
                seen.add((y2,x2))
                if Gin[y2][x2]==dd['bg']:
                    q.append((y2,x2,d+1))
                elif hit is None:
                    hit = (y2,x2); hitd = d+1
    f['flood_hit'] = hit is not None and hit in cells
    f['flood_d'] = hitd if hit in cells else 999
    # ray down shaft col from corner+1
    ray = [ (y,cx) for y in range(cy+1,H) if (y,cx) not in Ls ]
    f['ray_down'] = next((True for y,x in ray if Gin[y][x]!=dd['bg'] and (y,x) in cells), False)
    f['ray_down_block'] = next(( (y,x) for y,x in ray if Gin[y][x]!=dd['bg']), None) is not None and False or False
    # ray left along arm row
    rayl = [ (cy,x) for x in range(cx-1,-1,-1) if (cy,x) not in Ls ]
    f['ray_left'] = next((True for y,x in rayl if Gin[y][x]!=dd['bg'] and (y,x) in cells), False)
    return f

